import { useMutation, useQueryClient } from '@tanstack/react-query';

async function addComment(postId: string, body: string) {
  const res = await fetch(`/api/posts/${postId}/comments`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ body }),
  });
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

function CommentForm({ postId }: { postId: string }) {
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: (body: string) => addComment(postId, body),

    onSuccess: () => {
      // Invalidate both the individual post and the comments list
      queryClient.invalidateQueries({ queryKey: ['post', postId] });
      queryClient.invalidateQueries({ queryKey: ['comments', postId] });
    },

    onError: (error) => {
      console.error('Failed to add comment:', error);
    },
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); mutation.mutate(e.target.body.value); }}>
      <textarea name="body" disabled={mutation.isPending} />
      <button type="submit" disabled={mutation.isPending}>
        {mutation.isPending ? 'Postingâ€¦' : 'Post Comment'}
      </button>
    </form>
  );
}

